func TestTheSniffReadsTheSignatureAndNothingElse(emonT *testing.T) {
	port.AssertEq(emonT, rasterin.RsSniff(port.SrcOfBlob(port.HexBlob("89504e470d0a1a0a0000000d"))), rasterin.RsPng(), "PNG")
	port.AssertEq(emonT, rasterin.RsSniff(port.SrcOfBlob(port.HexBlob("ffd8ffe000104a46"))), rasterin.RsJpeg(), "JPEG")
	port.AssertEq(emonT, rasterin.RsSniff(port.SrcOfBlob(port.HexBlob("49492a0008000000"))), rasterin.RsTiff(), "TIFF, little endian")
	port.AssertEq(emonT, rasterin.RsSniff(port.SrcOfBlob(port.HexBlob("4d4d002a00000008"))), rasterin.RsTiff(), "TIFF, big endian")
	port.AssertEq(emonT, rasterin.RsSniff(port.SrcOfBlob(port.HexBlob("255044462d312e37"))), rasterin.RsNone(), "a PDF is none of them")
	port.AssertEq(emonT, rasterin.RsSniff(port.SrcOfBlob(port.HexBlob("89504e470d0a1a0b"))), rasterin.RsNone(), "a PNG signature with one byte wrong")
	port.AssertEq(emonT, rasterin.RsSniff(port.SrcOfBlob(port.HexBlob("89504e47"))), rasterin.RsNone(), "a PNG signature cut short")
	port.AssertEq(emonT, rasterin.RsSniff(port.SrcOfBlob(port.HexBlob("4949"))), rasterin.RsNone(), "too short to say")
	port.AssertEq(emonT, rasterin.RsSniff(port.SrcOfBlob(port.HexBlob("49492b0008000000"))), rasterin.RsNone(), "BigTIFF is not read")
	port.AssertEq(emonT, rasterin.RsCpt(463, 20000), 16668, "463 px at 200 dpi is 166.68 pt")
	port.AssertEq(emonT, rasterin.RsCpt(2481, 30000), 59544, "A4 at 300 dpi, rounded")
	port.AssertEq(emonT, rasterin.RsCpt(1, 100000000), 1, "never zero")
}

func unitOf(ans *port.Cells, rq *port.Cells, nodes *port.Cells, attrs *port.Cells, text *port.Cells, pages *port.Cells, info int32) int32 {
	var regions *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	return rasterin.RsUnit(port.SrcOfBlob(port.HexBlob("49492a0008000000")), 7, rasterin.RsTiff(), info, ans, rq, nodes, attrs, text, pages)
}

func TestTheFirstRoundAsksForFrameZeroAndNothingMore(emonT *testing.T) {
	var ans *port.Cells = port.NewCells()
	var rq *port.Cells = port.NewCells()
	port.AssertEq(emonT, unitOf(ans, rq, port.NewCells(), port.NewCells(), port.NewCells(), port.NewCells(), 0), plan.UsRequests(), "it asks")
	port.AssertEq(emonT, port.CellsLen(rq), 8, "one request of eight cells")
	port.AssertEq(emonT, plan.RecKind(rq, 0), plan.PkDecode(), "a decode")
	port.AssertEq(emonT, plan.RecId(rq, 0), 1, "frame 0 is id 1")
	port.AssertEq(emonT, plan.RqArg(rq, 0, 0), 7, "the input's index")
	port.AssertEq(emonT, plan.RqArg(rq, 0, 1), 0, "from its first byte")
	port.AssertEq(emonT, plan.RqArg(rq, 0, 2), 8, "the whole input")
	port.AssertEq(emonT, plan.RqArg(rq, 0, 3), plan.FltNone(), "a whole image file, not a PDF filter")
	port.AssertEq(emonT, plan.RqArg(rq, 0, 4), 0, "frame 0")
}

